// DpayCore shim — the ONLY money-critical shim. It produces a REAL, byte-exact Ed25519 wire that
// the FakeLedger's `sa.verify()` (ed25519-dalek `verify_strict`) accepts, so local pay flows settle
// for real. This is NOT a mock of the signing logic — it IS the signing logic, implemented in JS
// over @noble/ed25519 (RFC 8032; binary-compatible with dalek).
//
// The wire layout (field offsets/lengths/endian) is read from `dfx/wire_layout.json`, which is
// generated by `cargo run -p dpay-fixture --release -- wire-layout` from the REAL dpay_core types.
// So there is ONE source of truth — the Rust core — and the JS shim never hand-transcribes the
// layout. `tests/00-cross-val.mjs` re-signs the golden Authorization with this shim and asserts
// byte-identical sig + wire, which proves every local pay flow that uses this shim will settle on
// the real FakeLedger (which verifies sigs).
//
// The shim is installed into `react-native-web`'s `NativeModules.DpayCore` by `shims.ts`, so the
// real `app/App.tsx` reads it via `const {DpayCore} = NativeModules` — exactly the same seam as on
// device, where DpayCore is a Kotlin Turbo Module over libdpay_ffi.so.
import * as ed from '@noble/ed25519';
import { hexToBytes, bytesToHex } from '@noble/hashes/utils';

// Inline base64url codec (mirrors Rust's `URL_SAFE_NO_PAD`). @noble/hashes@1.6 does not export a
// base64 module under the package's `exports` map; rather than chase a version, the codec is small
// enough to inline (RFC 4648 §5, no padding). Bytes-for-bytes identical to base64::URL_SAFE_NO_PAD.
const B64_URL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const B64_URL_REV: Record<string, number> = (() => {
  const m: Record<string, number> = {};
  for (let i = 0; i < B64_URL.length; i++) m[B64_URL[i]] = i;
  return m;
})();
const base64url = {
  encode(bytes: Uint8Array): string {
    let out = '';
    for (let i = 0; i < bytes.length; i += 3) {
      const b0 = bytes[i];
      const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
      const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
      out += B64_URL[b0 >> 2];
      out += B64_URL[((b0 & 0x03) << 4) | (b1 >> 4)];
      if (i + 1 < bytes.length) out += B64_URL[((b1 & 0x0f) << 2) | (b2 >> 6)];
      if (i + 2 < bytes.length) out += B64_URL[b2 & 0x3f];
    }
    return out; // no padding (URL_SAFE_NO_PAD)
  },
  decode(s: string): Uint8Array {
    const cleaned = s.replace(/=+$/g, '');
    const bytes: number[] = [];
    for (let i = 0; i < cleaned.length; i += 4) {
      const c0 = B64_URL_REV[cleaned[i]];
      const c1 = B64_URL_REV[cleaned[i + 1]];
      const c2 = i + 2 < cleaned.length ? B64_URL_REV[cleaned[i + 2]] : undefined;
      const c3 = i + 3 < cleaned.length ? B64_URL_REV[cleaned[i + 3]] : undefined;
      if (c0 === undefined || c1 === undefined) throw new Error('base64url: bad char');
      bytes.push((c0 << 2) | (c1 >> 4));
      if (c2 !== undefined) bytes.push(((c1 & 0x0f) << 4) | (c2 >> 2));
      if (c3 !== undefined) bytes.push(((c2 & 0x03) << 6) | c3);
    }
    return new Uint8Array(bytes);
  },
};

// --- layout (single-sourced from dfx/wire_layout.json; never hand-transcribed) ----------------
//
// Path: from `e2e/web/dpay-core.ts`, the JSON lives two dirs up at `dfx/wire_layout.json`. Vite's
// `server.fs.allow` covers the repo root (see vite.config.js), so the build can read it. The harness
// regenerates it via `dpay-fixture wire-layout` if missing, so the layout is always the current one.
import layout from '../../dfx/wire_layout.json' assert { type: 'json' };

type FieldSpec = { offset: number; len: number; endian: 'le' | null };
type WireFieldSpec = { offset: number; len: number };
type Layout = {
  signing_len: number; wire_len: number; request_len: number; sig_len: number;
  pubkey_len: number; nonce_len: number; name_len: number; memo_len: number;
  fields: {
    from: FieldSpec; to: FieldSpec; amount: FieldSpec; nonce: FieldSpec;
    expiry: FieldSpec; currency: FieldSpec;
    from_name: FieldSpec; to_name: FieldSpec; memo: FieldSpec;
  };
  request_fields: {
    to: FieldSpec; amount: FieldSpec; nonce: FieldSpec; expiry: FieldSpec;
    currency: FieldSpec; to_name: FieldSpec; memo: FieldSpec;
  };
  wire_fields: { signing: WireFieldSpec; sig: WireFieldSpec; from_pub: WireFieldSpec };
  golden: {
    secret_hex: string; public_hex: string; to_hex: string; amount: number; nonce_hex: string;
    expiry: number; currency: number; signing_hex: string; sig_hex: string; wire_hex: string;
    request_hex: string; from_name_hex: string; to_name_hex: string; memo_hex: string;
    request_to_name_hex: string; request_memo_hex: string;
  };
  // Withdrawal (ckBTC→BTC) signing layout — variable-length (the destination is last). The fixed
  // prefix uses the SAME field widths as `fields` but a DIFFERENT order, so it gets its own section.
  withdraw: {
    fixed_len: number; addr_len_bytes: number;
    fields: {
      from_pubkey: FieldSpec; amount: FieldSpec; nonce: FieldSpec; expiry: FieldSpec;
      currency: FieldSpec; address_len: FieldSpec;
    };
    golden: {
      secret_hex: string; public_hex: string; destination: string; amount: number;
      nonce_hex: string; expiry: number; currency: number; signing_hex: string; sig_hex: string;
    };
  };
};

const L = layout as unknown as Layout;

// Sanity: the constants we read must match what we expect from the Rust core. Catches a stale or
// hand-edited wire_layout.json before it produces silently-wrong sigs.
function assertLayout() {
  const eq = (a: unknown, b: unknown, msg: string) => {
    if (a !== b) throw new Error(`DpayCore shim: wire_layout.json mismatch — ${msg} (got ${a}, expected ${b})`);
  };
  eq(L.signing_len, 196, 'signing_len');
  eq(L.wire_len, 292, 'wire_len');
  eq(L.request_len, 132, 'request_len');
  eq(L.sig_len, 64, 'sig_len');
  eq(L.pubkey_len, 32, 'pubkey_len');
  eq(L.nonce_len, 16, 'nonce_len');
  eq(L.name_len, 32, 'name_len');
  eq(L.memo_len, 32, 'memo_len');
  for (const [name, f] of Object.entries(L.fields)) {
    const ff = f as FieldSpec;
    if (ff.endian !== null && ff.endian !== 'le') {
      throw new Error(`DpayCore shim: unexpected endian ${ff.endian} for field ${name}`);
    }
  }
}
assertLayout();

// --- display name + memo codec (NUL-padded UTF-8, truncate to 32 bytes) -----------------------
//
// Mirrors `dpay_core::pad_name` / the canister's `display_field_to_string`. Fixed-width 32 B per
// field: UTF-8 encode, truncate to 32 bytes, trailing-NUL (0x00) pad. Empty = all zeros. Decode is
// lossy (TextDecoder fatal:false) + NUL-trimmed — NEVER throws (the "no silent errors" rule: a bad
// byte sequence becomes U+FFFD, not an exception).
const NAME_LEN = 32;

/** UTF-8-encode `s`, truncate to 32 bytes, NUL-pad to a fixed 32-byte array. */
function padName32(s: string): Uint8Array {
  const utf8 = new TextEncoder().encode(s);
  const buf = new Uint8Array(NAME_LEN);
  buf.set(utf8.subarray(0, NAME_LEN)); // truncate; the rest is already zero (NUL-pad)
  return buf;
}

/** Lossy-decode + NUL-trim a 32-byte name/memo field back to a string. Never throws. */
function trimName32(bytes: Uint8Array): string {
  let end = bytes.indexOf(0);
  if (end < 0) end = bytes.length;
  try {
    return new TextDecoder('utf-8', { fatal: false }).decode(bytes.subarray(0, end));
  } catch {
    return '';
  }
}

// --- low-level codec (operates only on the offsets/lengths/endian from the JSON) -------------

/** Decode a hex string into a fresh Uint8Array (errors mirror dpay_core::CodecError). */
function hex(h: string): Uint8Array {
  if (!/^[0-9a-fA-F]*$/.test(h) || h.length % 2 !== 0) {
    throw new Error('Length'); // mirrors CodecError::Length semantics for hex-shaped fields
  }
  return hexToBytes(h);
}

/** Write a little-endian u64 into `buf` at `offset`. */
function putU64Le(buf: Uint8Array, offset: number, val: number): void {
  // Bitwise on a Number works up to 2^53; for u64 amounts/expiry this is well under the safe range.
  // (Per-tx cap is 100_000 cents; expiry is unix-secs; neither approaches 2^53.)
  let v = Math.floor(val);
  for (let i = 0; i < 8; i++) {
    buf[offset + i] = v & 0xff;
    v = Math.floor(v / 0x100);
  }
}
function readU64Le(buf: Uint8Array, offset: number): number {
  let v = 0;
  for (let i = 7; i >= 0; i--) v = v * 0x100 + buf[offset + i];
  return v;
}
/** Write a little-endian u32. */
function putU32Le(buf: Uint8Array, offset: number, val: number): void {
  let v = Math.floor(val);
  for (let i = 0; i < 4; i++) {
    buf[offset + i] = v & 0xff;
    v = Math.floor(v / 0x100);
  }
}
function readU32Le(buf: Uint8Array, offset: number): number {
  let v = 0;
  for (let i = 3; i >= 0; i--) v = v * 0x100 + buf[offset + i];
  return v;
}

/**
 * Build the 196-byte signing buffer from a fully-formed Authorization. Mirrors
 * `Authorization::signing_bytes()` field-for-field using ONLY the offsets from `wire_layout.json`.
 * `from` is the signer's pubkey (the app always signs with the identity it generated). The three
 * 32-byte display fields (`from_name`/`to_name`/`memo`) are UTF-8 NUL-padded via `padName32`.
 */
function buildSigningBytes(fromHex: string, toHex: string, amount: number, nonceHex: string, expiry: number, currency: number, fromName = '', toName = '', memo = ''): Uint8Array {
  const from = hex(fromHex);
  const to = hex(toHex);
  const nonce = hex(nonceHex);
  if (from.length !== L.fields.from.len) throw new Error(`from length: ${from.length}`);
  if (to.length !== L.fields.to.len) throw new Error(`to length: ${to.length}`);
  if (nonce.length !== L.fields.nonce.len) throw new Error(`nonce length: ${nonce.length}`);
  const buf = new Uint8Array(L.signing_len);
  buf.set(from, L.fields.from.offset);
  buf.set(to, L.fields.to.offset);
  putU64Le(buf, L.fields.amount.offset, amount);
  buf.set(nonce, L.fields.nonce.offset);
  putU64Le(buf, L.fields.expiry.offset, expiry);
  putU32Le(buf, L.fields.currency.offset, currency);
  buf.set(padName32(fromName), L.fields.from_name.offset);
  buf.set(padName32(toName), L.fields.to_name.offset);
  buf.set(padName32(memo), L.fields.memo.offset);
  return buf;
}

/** Build the 292-byte wire (signing[0..196] | sig[196..260] | from_pub[260..292]). */
function buildWire(signing: Uint8Array, sig: Uint8Array, fromPub: Uint8Array): Uint8Array {
  const wire = new Uint8Array(L.wire_len);
  wire.set(signing, L.wire_fields.signing.offset);
  wire.set(sig, L.wire_fields.sig.offset);
  wire.set(fromPub, L.wire_fields.from_pub.offset);
  return wire;
}

/** Parse the 292-byte wire back into its parts (mirrors `SignedAuthorization::from_wire`). */
function parseWire(wireBytes: Uint8Array): {
  signing: Uint8Array; sig: Uint8Array; fromPub: Uint8Array;
  auth: { fromHex: string; toHex: string; amount: number; nonceHex: string; expiry: number; currency: number; fromName: string; toName: string; memo: string };
} {
  if (wireBytes.length !== L.wire_len) throw new Error('Length');
  const signing = wireBytes.slice(L.wire_fields.signing.offset, L.wire_fields.signing.offset + L.wire_fields.signing.len);
  const sig = wireBytes.slice(L.wire_fields.sig.offset, L.wire_fields.sig.offset + L.wire_fields.sig.len);
  const fromPub = wireBytes.slice(L.wire_fields.from_pub.offset, L.wire_fields.from_pub.offset + L.wire_fields.from_pub.len);
  const fromHex = bytesToHex(signing.slice(L.fields.from.offset, L.fields.from.offset + L.fields.from.len));
  const toHex = bytesToHex(signing.slice(L.fields.to.offset, L.fields.to.offset + L.fields.to.len));
  const amount = readU64Le(signing, L.fields.amount.offset);
  const nonceHex = bytesToHex(signing.slice(L.fields.nonce.offset, L.fields.nonce.offset + L.fields.nonce.len));
  const expiry = readU64Le(signing, L.fields.expiry.offset);
  const currency = readU32Le(signing, L.fields.currency.offset);
  const fromName = trimName32(signing.slice(L.fields.from_name.offset, L.fields.from_name.offset + L.fields.from_name.len));
  const toName = trimName32(signing.slice(L.fields.to_name.offset, L.fields.to_name.offset + L.fields.to_name.len));
  const memo = trimName32(signing.slice(L.fields.memo.offset, L.fields.memo.offset + L.fields.memo.len));
  return { signing, sig, fromPub, auth: { fromHex, toHex, amount, nonceHex, expiry, currency, fromName, toName, memo } };
}

/** Build the 132-byte request (merchant's QR) from the request fields. The `to_name` + `memo` are
 *  the merchant-defined display fields (NUL-padded UTF-8 via `padName32`). */
function buildRequestBytes(toHex: string, amount: number, nonceHex: string, expiry: number, currency: number, toName = '', memo = ''): Uint8Array {
  const to = hex(toHex);
  const nonce = hex(nonceHex);
  if (to.length !== L.pubkey_len) throw new Error(`to length: ${to.length}`);
  if (nonce.length !== L.nonce_len) throw new Error(`nonce length: ${nonce.length}`);
  // Request layout = to(32) | amount_le(8) | nonce(16) | expiry_le(8) | currency_le(4) |
  // to_name(32) | memo(32) — every offset/length read from `wire_layout.json`'s `request_fields`.
  const buf = new Uint8Array(L.request_len);
  buf.set(to, L.request_fields.to.offset);
  putU64Le(buf, L.request_fields.amount.offset, amount);
  buf.set(nonce, L.request_fields.nonce.offset);
  putU64Le(buf, L.request_fields.expiry.offset, expiry);
  putU32Le(buf, L.request_fields.currency.offset, currency);
  buf.set(padName32(toName), L.request_fields.to_name.offset);
  buf.set(padName32(memo), L.request_fields.memo.offset);
  return buf;
}

/**
 * Build the canonical withdraw signing bytes (mirrors `dpay_core::WithdrawAuth::signing_bytes`
 * EXACTLY): `from_pubkey(32) | amount_le(8) | nonce(16) | expiry_le(8) | currency_le(4) |
 * addr_len_le(4) | addr_utf8`. Variable-length, so unlike `buildSigningBytes` this returns a
 * right-sized buffer. Every offset/length is read from `wire_layout.json`'s `withdraw` section —
 * never hand-transcribed. This is the drift-detector: if it ever diverges from the Rust core, the
 * FakeLedger/canister verify rejects the sig and the e2e withdraw flow goes RED.
 */
function buildWithdrawSigningBytes(
  fromHex: string, btcAddress: string, amount: number, nonceHex: string, expiry: number, currency: number,
): Uint8Array {
  const W = L.withdraw;
  const from = hex(fromHex);
  const nonce = hex(nonceHex);
  if (from.length !== L.pubkey_len) throw new Error(`from length: ${from.length}`);
  if (nonce.length !== L.nonce_len) throw new Error(`nonce length: ${nonce.length}`);
  const addr = new TextEncoder().encode(btcAddress);
  const buf = new Uint8Array(W.fixed_len + W.addr_len_bytes + addr.length);
  buf.set(from, W.fields.from_pubkey.offset);
  putU64Le(buf, W.fields.amount.offset, amount);
  buf.set(nonce, W.fields.nonce.offset);
  putU64Le(buf, W.fields.expiry.offset, expiry);
  putU32Le(buf, W.fields.currency.offset, currency);
  // u32 LE address length (well under 2^32 for any real BTC address).
  putU32Le(buf, W.fields.address_len.offset, addr.length);
  buf.set(addr, W.fields.address_len.offset + W.addr_len_bytes);
  return buf;
}

// --- the public DpayCore surface (mirrors app/App.tsx's DpayCoreApi type) ---------------------

async function generateKeypair(): Promise<{ secretHex: string; publicHex: string }> {
  // The app generates an ephemeral key on first run. @noble/ed25519's utils.randomPrivateKey pulls
  // from crypto.getRandomValues (available in the browser). Mirrors `dpay_core::generate_keypair`.
  const secret = ed.utils.randomPrivateKey();
  const pub = await ed.getPublicKeyAsync(secret);
  return { secretHex: bytesToHex(secret), publicHex: bytesToHex(pub) };
}

async function signAuthorization(secretHex: string, toHex: string, amount: number, nonceHex: string, expiry: number, currency: number, fromName = '', toName = '', memo = ''): Promise<string> {
  // Per the on-device contract: returns the wire as a hex string. The app then hands it to
  // encodeQr() to make the QR the merchant scans / submits. `fromName` is the payer's own display
  // name; `toName` + `memo` are copied from the scanned request (merchant-defined).
  const secret = hex(secretHex);
  const pub = await ed.getPublicKeyAsync(secret);
  const signing = buildSigningBytes(bytesToHex(pub), toHex, amount, nonceHex, expiry, currency, fromName, toName, memo);
  const sig = await ed.signAsync(signing, secret);
  const wire = buildWire(signing, sig, pub);
  return bytesToHex(wire);
}

async function encodeRequest(toHex: string, amount: number, nonceHex: string, expiry: number, currency: number, toName = '', memo = ''): Promise<string> {
  // Mirrors `PaymentRequest::encode` — base64url of the 132-byte request. The merchant QR is now
  // plain base64url (the `to_name` lives inside the bytes; the old `|name` suffix is gone).
  return base64url.encode(buildRequestBytes(toHex, amount, nonceHex, expiry, currency, toName, memo));
}

async function decodeRequest(qr: string): Promise<{ toHex: string; amount: number; nonceHex: string; expiry: number; currency: number; toName: string; memo: string }> {
  // Mirrors `PaymentRequest::decode`. The QR is plain base64url now (the name lives in the bytes);
  // tolerate a stray `|name` suffix defensively, but it carries no name anymore.
  const b64 = qr.includes('|') ? qr.slice(0, qr.indexOf('|')) : qr;
  let bytes: Uint8Array;
  try {
    bytes = base64url.decode(b64);
  } catch {
    throw new Error('Base64');
  }
  if (bytes.length !== L.request_len) throw new Error('Length');
  const toHex = bytesToHex(bytes.slice(L.request_fields.to.offset, L.request_fields.to.offset + L.request_fields.to.len));
  const amount = readU64Le(bytes, L.request_fields.amount.offset);
  const nonceHex = bytesToHex(bytes.slice(L.request_fields.nonce.offset, L.request_fields.nonce.offset + L.request_fields.nonce.len));
  const expiry = readU64Le(bytes, L.request_fields.expiry.offset);
  const currency = readU32Le(bytes, L.request_fields.currency.offset);
  const toName = trimName32(bytes.slice(L.request_fields.to_name.offset, L.request_fields.to_name.offset + L.request_fields.to_name.len));
  const memo = trimName32(bytes.slice(L.request_fields.memo.offset, L.request_fields.memo.offset + L.request_fields.memo.len));
  return { toHex, amount, nonceHex, expiry, currency, toName, memo };
}

async function encodeQr(wireHex: string): Promise<string> {
  // Mirrors `SignedAuthorization::encode` — base64url of the 292-byte wire. The app's QR dance uses
  // this exact encoding; the relay's `POST /api/v1/pay` decodes it back via `decode_body` (JSON path).
  return base64url.encode(hex(wireHex));
}

async function verifyWire(wireHex: string): Promise<boolean> {
  // Mirrors `SignedAuthorization::verify`. Returns false on ANY malformed input (never throws), so
  // the app's `if (!(await DpayCore.verifyWire(wire))) throw` fires on a tampered sig.
  try {
    const wire = hex(wireHex);
    const parsed = parseWire(wire);
    // from_pub MUST equal the from field embedded in the signing buffer (dpay_core::PubkeyMismatch).
    if (parsed.auth.fromHex !== bytesToHex(parsed.fromPub)) return false;
    return await ed.verifyAsync(parsed.sig, parsed.signing, parsed.fromPub);
  } catch {
    return false;
  }
}

/**
 * Sign a withdrawal authorization (mirrors the FFI `sign_withdrawal`). Returns the 64-byte Ed25519
 * signature as hex over the canonical `WithdrawAuth::signing_bytes()` (built via
 * `buildWithdrawSigningBytes`, reading `wire_layout.json`'s `withdraw` section — single source of
 * truth). The app hands `{from, destination, amount, nonce, expiry, currency, sig}` to
 * `POST /api/v1/withdraw`; the FakeLedger/canister verify this exact signature before moving funds.
 */
async function signWithdrawal(
  secretHex: string, btcAddress: string, amount: number, nonceHex: string, expiry: number, currency: number,
): Promise<string> {
  const secret = hex(secretHex);
  const pub = await ed.getPublicKeyAsync(secret);
  const signing = buildWithdrawSigningBytes(bytesToHex(pub), btcAddress, amount, nonceHex, expiry, currency);
  const sig = await ed.signAsync(signing, secret);
  return bytesToHex(sig);
}

/**
 * Build the canonical 108-byte receipt claim (R2). Mirrors `dpay_core::ReceiptClaim::signing_bytes`
 * EXACTLY: `nonce(16) | from(32) | to(32) | amount_le(8) | currency_le(4) | block_index_le(8) |
 * settle_ts_le(8)`. This is the drift-detector: if it ever diverges from the Rust core, the FakeLedger
 * (which signs with ed25519-dalek over the same layout) produces a sig this @noble verify rejects,
 * and the e2e pay flows go RED. Field widths match `wire_layout.json`'s nonce/pubkey/amount/currency.
 */
function buildReceiptClaimBytes(
  nonceHex: string, fromHex: string, toHex: string, amount: number, currency: number,
  blockIndex: number, settleTs: number,
): Uint8Array {
  const nonce = hex(nonceHex);
  const from = hex(fromHex);
  const to = hex(toHex);
  if (nonce.length !== L.nonce_len) throw new Error(`nonce length: ${nonce.length}`);
  if (from.length !== L.pubkey_len) throw new Error(`from length: ${from.length}`);
  if (to.length !== L.pubkey_len) throw new Error(`to length: ${to.length}`);
  const buf = new Uint8Array(L.nonce_len + L.pubkey_len + L.pubkey_len + 8 + 4 + 8 + 8); // 108
  let off = 0;
  buf.set(nonce, off); off += L.nonce_len;
  buf.set(from, off); off += L.pubkey_len;
  buf.set(to, off); off += L.pubkey_len;
  putU64Le(buf, off, amount); off += 8;
  putU32Le(buf, off, currency); off += 4;
  putU64Le(buf, off, blockIndex); off += 8;
  putU64Le(buf, off, settleTs);
  return buf;
}

async function verifyReceiptSig(
  nonceHex: string, fromHex: string, toHex: string, amount: number, currency: number,
  blockIndex: number, settleTs: number, receiptSigHex: string, pubkeyHex: string,
): Promise<boolean> {
  // Mirrors `dpay_core::verify_receipt` / the FFI `verify_receipt_sig`. Returns false on any bad
  // input (never throws), so the app gates "Paid ✓" on a clean true.
  try {
    const sig = hex(receiptSigHex);
    const pub = hex(pubkeyHex);
    if (sig.length !== L.sig_len) return false;
    if (pub.length !== L.pubkey_len) return false;
    const claim = buildReceiptClaimBytes(nonceHex, fromHex, toHex, amount, currency, blockIndex, settleTs);
    return await ed.verifyAsync(sig, claim, pub);
  } catch {
    return false;
  }
}

/** Synchronous RNG-backed nonce, mirroring `randNonceHex()` in App.tsx. Uses the browser CSPRNG. */
export function randNonceHex(): string {
  const buf = new Uint8Array(L.nonce_len);
  if (typeof globalThis.crypto?.getRandomValues === 'function') {
    globalThis.crypto.getRandomValues(buf);
  } else {
    // Fallback (shouldn't happen in a real browser) — preserves the contract rather than crashing.
    for (let i = 0; i < buf.length; i++) buf[i] = Math.floor(Math.random() * 256);
  }
  return bytesToHex(buf);
}

// Exported for `tests/00-cross-val.mjs` — gives the test direct access to the byte builders so the
// cross-validation can compare against the golden bytes without going through the async RN bridge.
export const __test = {
  layout: L,
  buildSigningBytes,
  buildWithdrawSigningBytes,
  buildWire,
  buildRequestBytes,
  parseWire,
  padName32,
  trimName32,
  bytesToHex,
  hexToBytes,
};

// The shape App.tsx expects on `NativeModules.DpayCore` (see `DpayCoreApi` in App.tsx). `nfcStatus`
// defaults to 'unknown' (so the NfcPill stays hidden and NfcTap never mounts — the right web
// default), but a test can flip it to 'ready' via `window.__DPAY_TEST_NFC_STATUS` (Wave E flow 11)
// so the NFC tap view arms and the `__DPAY_TEST_NFC_SESSION` seam can drive its phases.
async function nfcStatus(): Promise<string> {
  if (typeof window !== 'undefined') {
    const v = (window as any).__DPAY_TEST_NFC_STATUS;
    if (typeof v === 'string' && v.length > 0) return v;
  }
  return 'unknown';
}

export const DpayCore = {
  generateKeypair,
  signAuthorization,
  signWithdrawal,
  encodeRequest,
  decodeRequest,
  encodeQr,
  verifyWire,
  verifyReceiptSig,
  nfcStatus,
};
export type DpayCoreShim = typeof DpayCore;
